// Limit number of emails per execution (recommended: 30-50 per run to protect Gmail reputation)
const DAILY_LIMIT = 100;
return $input.all().slice(0, DAILY_LIMIT);

// Robust contact resolver that never breaks even across AI Agent
let source = {};
try {
  const loopNode = $('Loop Over Items');
  const runIndex = loopNode.context?.currentRunIndex;
  const contacts = $('Limit Daily Batch').all();
  if (contacts && typeof runIndex === 'number' && contacts[runIndex]) {
    source = contacts[runIndex].json;
  }
} catch (e) {}

if (!source || !source.Email) {
  try {
    source = $('Loop Over Items').item.json;
  } catch (e) {}
}

if (!source || !source.Email) {
  try {
    source = $('Has Recipient Email').item.json;
  } catch (e) {}
}

if (!source || !source.Email) {
  source = $json;
}

const raw = $json.output ?? $json.text ?? $json.response ?? $json.message?.content ?? '';
let parsed = null;
const rawStr = typeof raw === 'string' ? raw : JSON.stringify(raw);

try {
  const cleanedJsonStr = rawStr.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  parsed = JSON.parse(cleanedJsonStr);
} catch (e) {
  const match = rawStr.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      const subjMatch = rawStr.match(/"subject"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i);
      const hookMatch = rawStr.match(/"(?:hook|intro|opening)"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i);
      const bodyMatch = rawStr.match(/"(?:body|message)"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i);
      if (subjMatch || hookMatch || bodyMatch) {
        parsed = {
          subject: subjMatch ? subjMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') : '',
          hook: hookMatch ? hookMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') : '',
          body: bodyMatch ? bodyMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') : ''
        };
      }
    }
  }
}

const recipientEmail = (source.Email || source.email || source['Email Address'] || source['email address'] || source['Email ID'] || source['email id'] || Object.entries(source || {}).find(([k]) => /email|e-mail/i.test(k.trim()))?.[1] || Object.values(source || {}).find(v => typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) || '').trim();
const recipientName = (source.Name || source.name || '').trim();
const firstName = recipientName.split(/\s+/)[0] || 'there';
const company = (source.Company || source.company || '').trim();
const title = (source.Title || source.title || 'Hiring Manager').trim();

// 1. Dynamic Subject Line with Company Name
let subject = parsed && typeof parsed.subject === 'string' ? parsed.subject.trim() : '';
subject = subject.replace(/^[\"']|[\"']$/g, '').replace(/\[[^\]]*\]/g, '').replace(/[-–—\s]+$/, '').trim();
if (company) {
  subject = subject.replace(/\b(?:the|your)\s+company\b/gi, company);
}
if (!subject || /^opportunities at/i.test(subject) || /^job application/i.test(subject) || /^application/i.test(subject) || subject.includes('[') || subject.length < 10) {
  subject = company ? `Applied AI Role / Question about ${company}’s AI Roadmap` : 'Applied AI Role / Question about your AI Roadmap';
}

// 2. Extract and Refactor Personalized Hook
let personalizedHook = '';

if (parsed && typeof parsed.hook === 'string' && parsed.hook.trim()) {
  personalizedHook = parsed.hook.trim();
} else if (parsed && typeof (parsed.body || parsed.message) === 'string' && (parsed.body || parsed.message).trim()) {
  const candidateBody = (parsed.body || parsed.message).trim();
  const hookMatch = candidateBody.match(/(?:I’ve|I've|I\s+have\s+been|I’m|I'm)\s+(?:following|particularly\s+interested\s+in|admiring)[^.!?]*[.!?]/i);
  if (hookMatch) {
    personalizedHook = hookMatch[0].trim();
  }
} else if (rawStr && !rawStr.startsWith('{')) {
  const hookMatch = rawStr.match(/(?:I’ve|I've|I\s+have\s+been|I’m|I'm)\s+(?:following|particularly\s+interested\s+in|admiring)[^.!?]*[.!?]/i);
  if (hookMatch) {
    personalizedHook = hookMatch[0].trim();
  }
}

// Clean and sanitize hook
if (personalizedHook) {
  personalizedHook = personalizedHook.replace(/^[\"']|[\"']$/g, '').replace(/\b(?:the|your)\s+company\b/gi, company || 'your team').trim();
  personalizedHook = personalizedHook.replace(/^(?:Hi|Hello|Hey)\s+[^,]+,\s*/i, '');
  personalizedHook = personalizedHook.replace(/^My name is[^.]*\.\s*/i, '');
}

// Fallback high-converting hook if model didn't provide one
if (!personalizedHook || personalizedHook.length < 20) {
  personalizedHook = company
    ? `I’ve been following ${company}’s recent work in productionizing Generative AI, especially your team’s focus on scaling intelligent production workflows.`
    : `I’ve been following your team’s recent work in productionizing Generative AI and scaling intelligent production workflows.`;
}

// 3. Assemble Master Template (links on separate lines)
const PORTFOLIO_URL = 'https://tusharahul.netlify.app';
const RESUME_URL = 'https://drive.google.com/file/d/1LdWTaK1wir3d-tAdkDc52F7LEc7cELtl/view?usp=sharing';
const GITHUB_URL = 'https://github.com/Rahul6158';
const LINKEDIN_URL = 'https://linkedin.com/in/tusha-rahul';
const FULL_NAME = 'Tusha Rahul Bellamkonda';

const emailBody = [
  `Hi ${firstName},`,

  personalizedHook,

  `I’m an Applied AI Engineer specializing in taking AI concepts and shipping them into reliable production applications. At my current role, I recently:\n• Optimized a multi-tenant RAG platform, boosting retrieval accuracy from 58% to 85% using HNSW Hybrid search.\n• Built a Text-to-SQL Agent for complex data analytics that cut query creation times by 40%.`,

  `I’d love to learn more about the engineering challenges your team is tackling next. Do you have 15 minutes for a brief chat this week?`,

  `Best,\n${FULL_NAME}\nApplied AI Engineer\nPortfolio: ${PORTFOLIO_URL}\nResume: ${RESUME_URL}\nGitHub: ${GITHUB_URL}\nLinkedIn: ${LINKEDIN_URL}`
].join('\n\n');

return [{
  json: {
    ...source,
    Email: recipientEmail,
    email: recipientEmail,
    Name: recipientName,
    Company: company,
    Title: title,
    emailSubject: subject,
    emailBody: emailBody
  }
}];
